preConditionHook:
// CONTEXT FILTER, not a signal: the market is within a few bars of a breakout
// and is in a pullback of one to about five bars. It says the setup on the
// table is a breakout PULLBACK rather than a failed breakout, and it is meant
// to be ANDed with whatever entry rule shares the pane.
//
// The breakout bar is found by the same bounded backward scan
// BreakoutPullbackEntry uses -- the most recent bar k in 1..startWindow whose
// close is beyond the extreme of the breakoutLookback bars ending one bar
// before it, the level open-coded because a function-history reference at a
// VARIABLE offset is not available (Extremes() is EL source and is exactly
// this loop), and "most recent" carried by the brkUpBar == -1 guard rather
// than a loop break, because EasyLanguage has none. Bars since the breakout
// is k, and the pullback so far is k - 1 bars, so both merged terms are read
// off k.
//
// It is NOT BreakoutPullbackEntry with a term dropped in the sense that
// matters: this fires on EVERY bar of the pullback, that one only on the bar
// the pullback ends. breakoutLookback is promoted to an input at
// BreakoutPullbackEntry's default -- the sources say "a breakout" and leave
// the level implicit -- so the two can be tuned together.
//
// The deepest bar touched is startWindow + breakoutLookback.
brkUpBar = -1;
brkDnBar = -1;
for (int k = 1; k <= (int)startWindow; ++k) {
    double lvlHigh = high[k + 1];
    double lvlLow = low[k + 1];
    for (int j = k + 2; j <= k + (int)breakoutLookback; ++j) {
        if (el_gt(high[j], lvlHigh)) lvlHigh = high[j];
        if (el_lt(low[j], lvlLow)) lvlLow = low[j];
    }
    if (brkUpBar == -1 && el_gt(close[k], lvlHigh)) brkUpBar = k;
    if (brkDnBar == -1 && el_lt(close[k], lvlLow)) brkDnBar = k;
}
pbUp = brkUpBar - 1;
pbDn = brkDnBar - 1;
inWindowUp = brkUpBar != -1 && pbUp >= 1 && el_le((double)pbUp, maxPullbackBars);
inWindowDn = brkDnBar != -1 && pbDn >= 1 && el_le((double)pbDn, maxPullbackBars);
